<template><BtgPageContainer as="section" class="community-page"><RouterLink :to="communityModerationPath(course())">Back to moderation</RouterLink><div v-if="!thread" role="status">Loading discussion…</div><template v-else><h1>{{thread.title}}</h1><p aria-live="polite">{{status}}</p><BtgButton :disabled="pending" @click="toggleThread">{{thread.state==='HIDDEN'?'Unhide thread':'Hide thread'}}</BtgButton><ol class="community-posts"><li v-for="p in thread.posts" :key="p.postId"><article><p v-if="p.state==='HIDDEN'">Hidden from participants</p><p class="community-posts__body">{{p.body}}</p><BtgButton v-if="!p.isOpeningPost" :disabled="pending" @click="togglePost(p.postId,p.state)">{{p.state==='HIDDEN'?'Unhide post':'Hide post'}}</BtgButton></article></li></ol></template></BtgPageContainer></template>
<script setup lang="ts">import{onBeforeUnmount,ref,watch}from'vue';import{useRoute}from'vue-router';import BtgButton from'../components/BtgButton.vue';import BtgPageContainer from'../components/BtgPageContainer.vue';import{communityModerationPath,getCommunityThreadForModeration,hideCommunityPost,hideCommunityThread,unhideCommunityPost,unhideCommunityThread,type CommunityModeratorThread}from'../courses/community';const route=useRoute(),thread=ref<CommunityModeratorThread>(),status=ref(''),pending=ref(false);let active=true,n=0;const course=()=>String(route.params.courseId??''),id=()=>String(route.params.threadId??'');async function load(){const v=++n;try{const x=await getCommunityThreadForModeration(course(),id());if(active&&v===n)thread.value=x}catch{if(active&&v===n)status.value='Discussion unavailable.'}}watch([()=>route.params.courseId,()=>route.params.threadId],load,{immediate:true});onBeforeUnmount(()=>{active=false;n++});async function toggleThread(){if(!thread.value||pending.value)return;pending.value=true;try{if(thread.value.state==='HIDDEN')await unhideCommunityThread(course(),id());else await hideCommunityThread(course(),id());await load();status.value='Thread visibility updated.'}catch{status.value='Visibility could not be updated.'}finally{pending.value=false}}async function togglePost(post:string,state:string){if(pending.value)return;pending.value=true;try{if(state==='HIDDEN')await unhideCommunityPost(course(),id(),post);else await hideCommunityPost(course(),id(),post);await load();status.value='Post visibility updated.'}catch{status.value='Visibility could not be updated.'}finally{pending.value=false}}</script>
